 static Node*
 get_head_value_node(Node* node, int exact, regex_t* reg)
 {
   Node* n = NULL_NODE;

   switch (NODE_TYPE(node)) {
   case NODE_BACKREF:
   case NODE_ALT:
 #ifdef USE_CALL
   case NODE_CALL:
 #endif
     break;

   case NODE_CTYPE:
     if (CTYPE_(node)->ctype == CTYPE_ANYCHAR)
       break;
     /* fall */
   case NODE_CCLASS:
     if (exact == 0) {
       n = node;
     }
     break;

   case NODE_LIST:
     n = get_head_value_node(NODE_CAR(node), exact, reg);
     break;

   case NODE_STRING:
     {
       StrNode* sn = STR_(node);

       if (sn->end <= sn->s)
         break;

       if (exact == 0 ||
           ! NODE_IS_IGNORECASE(node) || NODE_STRING_IS_CRUDE(node)) {
         n = node;
       }
     }
     break;

   case NODE_QUANT:
     {
       QuantNode* qn = QUANT_(node);
       if (qn->lower > 0) {
         if (IS_NOT_NULL(qn->head_exact))
           n = qn->head_exact;
         else
           n = get_head_value_node(NODE_BODY(node), exact, reg);
       }
     }
     break;

   case NODE_BAG:
     {
       BagNode* en = BAG_(node);
       switch (en->type) {
       case BAG_OPTION:
-        {
-          OnigOptionType options = reg->options;
-
-          reg->options = BAG_(node)->o.options;
-          n = get_head_value_node(NODE_BODY(node), exact, reg);
-          reg->options = options;
-        }
-        break;
-
       case BAG_MEMORY:
       case BAG_STOP_BACKTRACK:
       case BAG_IF_ELSE:
         n = get_head_value_node(NODE_BODY(node), exact, reg);
         break;
       }
     }
     break;

   case NODE_ANCHOR:
     if (ANCHOR_(node)->type == ANCR_PREC_READ)
       n = get_head_value_node(NODE_BODY(node), exact, reg);
     break;

   case NODE_GIMMICK:
   default:
     break;
   }

   return n;
 }

 static int
 check_called_node_in_look_behind(Node* node, int not)
 {
   int r;

   r = 0;

   switch (NODE_TYPE(node)) {
   case NODE_LIST:
   case NODE_ALT:
     do {
       r = check_called_node_in_look_behind(NODE_CAR(node), not);
     } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
     break;

   case NODE_QUANT:
     r = check_called_node_in_look_behind(NODE_BODY(node), not);
     break;

   case NODE_BAG:
     {
       BagNode* en = BAG_(node);

       if (en->type == BAG_MEMORY) {
         if (NODE_IS_MARK1(node))
           return 0;
         else {
           NODE_STATUS_ADD(node, MARK1);
           r = check_called_node_in_look_behind(NODE_BODY(node), not);
           NODE_STATUS_REMOVE(node, MARK1);
         }
       }
       else {
         r = check_called_node_in_look_behind(NODE_BODY(node), not);
         if (r == 0 && en->type == BAG_IF_ELSE) {
           if (IS_NOT_NULL(en->te.Then)) {
             r = check_called_node_in_look_behind(en->te.Then, not);
             if (r != 0) break;
           }
           if (IS_NOT_NULL(en->te.Else)) {
             r = check_called_node_in_look_behind(en->te.Else, not);
           }
         }
       }
     }
     break;

   case NODE_ANCHOR:
     if (IS_NOT_NULL(NODE_BODY(node)))
       r = check_called_node_in_look_behind(NODE_BODY(node), not);
     break;

   case NODE_GIMMICK:
     if (NODE_IS_ABSENT_WITH_SIDE_EFFECTS(node) != 0)
       return 1;
     break;

